window.products.push({"id":407010,"name":"DISTINCTIVS White and Gold 50th Birthday Party Invitations - 10 Cards with Envelopes","category":"homeandappliances","retail price":12.99,"sale price":null,"image":"https://m.media-amazon.com/images/I/81BFyQ0698L._AC_SL1500_.jpg","description":"10 CARDS WITH ENVELOPES: white and gold 50th birthday invitations are perfect for women or men turning 50. PREMIUM CARDSTOCK: 50th birthday invitation cards are 5\" x 7\" - post-card style, non-folding with Celebrate 50 design. SPACIOUS LINES for you to fill in event and RSVP information for your special 50th birthday party for him or her. SELF-SEALING metallic gold envelopes included to perfectly match the white and gold 50th birthday party invites. Add a LITTLE SOMETHING EXTRA to your white and gold 50th birthday party supplies with these fill in the blank invitations and envelopes.","images":["https://m.media-amazon.com/images/I/81BFyQ0698L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"DISTINCTIVS","source_asin":"B07NJ9NR8X","category_path":"Home & Kitchen"},"sku":"BM-407010","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B07NJ9NR8X","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B07NJ9NR8X","price_pending":true,"merchant_ready":false});
